from fractions import Fraction as Q
Z=(Q(0),)*4;O=(Q(1),Q(0),Q(0),Q(0));S=(Q(0),Q(1),Q(0),Q(0));I=(Q(0),Q(0),Q(1),Q(0))
def a(x,y):return tuple(x[k]+y[k]for k in range(4))
def s(q,x):return tuple(q*z for z in x)
def n(x):return s(-1,x)
def c(x):return(x[0],x[1],-x[2],-x[3])
def m(x,y):
 A,B,C,D=x;E,F,G,H=y
 return(A*E+3*B*F-C*G-3*D*H,A*F+B*E-C*H-D*G,A*G+3*B*H+C*E+3*D*F,A*H+B*G+C*F+D*E)
def sm(xs):
 z=Z
 for x in xs:z=a(z,x)
 return z
def mm(A,B):return[[sm(m(A[i][k],B[k][j])for k in range(len(B)))for j in range(len(B[0]))]for i in range(len(A))]
def dg(A):return[[c(A[j][i])for j in range(len(A))]for i in range(len(A[0]))]
def kr(A,B):return[[m(A[i//len(B)][j//len(B[0])],B[i%len(B)][j%len(B[0])])for j in range(len(A[0])*len(B[0]))]for i in range(len(A)*len(B))]
def scalar(M,x):assert M==[[x,Z],[Z,x]]
def gram(M,q):assert mm(dg(M),M)==[[s(q,O),Z],[Z,s(q,O)]]
ID=[[O,Z],[Z,O]];P=[[O,Z,Z,Z],[Z,Z,O,Z],[Z,O,Z,Z],[Z,Z,Z,O]];EA=[[O],[Z],[Z],[O]];EB=[[Z],[O],[n(O)],[Z]];JB=[[O,Z],[Z,n(O)]]
Wg=[[a(n(S),I),Z],[Z,s(-2,I)],[a(O,m(I,S)),Z],[Z,s(2,O)]];Wh=[[c(x)for x in r]for r in Wg];ag=s(Q(1,2),a(n(S),n(I)));ah=c(ag);Ug=[[m(ag,x)for x in r]for r in Wg];Uh=[[m(ah,x)for x in r]for r in Wh];Pg=mm(P,Ug);Ph=mm(P,Uh)
CL=[mm(kr(Ug,ID),Ph),mm(kr(Uh,ID),Pg)];CR=[mm(kr(ID,Pg),Uh),mm(kr(ID,Ph),Ug)];FL=[mm(kr(Pg,ID),Ph),mm(kr(Ph,ID),Pg)];FR=[kr(ID,EA),mm(kr(ID,EB),JB)]
for M in CL+CR+FL:gram(M,64)
for M in FR:gram(M,2)
EC=[[Z,s(64,O)],[s(64,O),Z]];EF=[[s(8,O),s(-8,I)],[s(8,O),s(8,I)]]
for A,LS,RS in ((EC,CL,CR),(EF,FL,FR)):
 for p in range(2):
  for q in range(2):scalar(mm(dg(LS[p]),RS[q]),A[p][q])
print({'field':'Q(sqrt(3),i)','CFC_cleared':[['0','64'],['64','0']],'FCC_cleared':[['8','-8i'],['8','8i']],'F_CFC':'[[0,1],[1,0]]','F_FCC':'1/sqrt(2)[[1,-i],[1,i]]','exact_grams_overlaps_unitarity':True})
